import {Game} from './engine.js';
export function packGame(game){const {random,player,map,platforms,...state}=game;return {...state,mapId:map.id,playerId:player.id,fighters:state.fighters.map(f=>({...f,blindContacts:[...(f.blindContacts||[])],touching:[...(f.touching||[])],dashHits:[...(f.dashHits||[])],slashHits:[...(f.slashHits||[])]}))};}
export function unpackGame(state,random=Math.random,playerId=state.playerId){const game=new Game(state.fighters[0].baseType,random,state.mapId);Object.assign(game,state);game.fighters=state.fighters.map(f=>({...f,blindTime:f.blindTime||0,blindAura:f.blindAura||0,blindContacts:new Set(f.blindContacts||[]),touching:new Set(f.touching),dashHits:new Set(f.dashHits),slashHits:new Set(f.slashHits)}));game.player=game.fighters.find(f=>f.id===playerId)||game.fighters[0];game.won=game.winnerId===game.player.id;return game;}
